/**
 * Investor pricing matrix.
 *
 * This is the half of Phase 1 that does not exist anywhere yet. Verified against the live
 * org: there is NO stored per-investor pricing in CRM — no multiplier field, and
 * `Tranche_Pricing` is null on every 2026 tranche. Which matches Gabe:
 *
 *   "here's the thing where if we were to settle the trench, then we would need it because
 *    I have no idea what the fuck the pricing is for... That's because we don't have a
 *    pricing dashboard."
 *
 * So the tool has to CREATE this, not read it.
 *
 * ── The key ────────────────────────────────────────────────────────────────────────────
 * Derived from Tranche 77's 100 real deals: a pricing row is identified by
 *
 *     (Pre_Pay_Pct_of_SOW , Tax_Credit_Percentage)  ->  Pre_Paid_Percentage_of_Bill_of_Sale
 *
 * Every observed (SOW, tax-credit) pair mapped to exactly one BoS percentage — 0.75/.40
 * always gave .6589, 0.70/.50 always gave .5905, and so on. Tax credit is itself the EC/DC
 * rubric: 0.30 base + 0.10 energy community + 0.10 domestic content. That is what the spec
 * calls "deal-type rubrics (EC/DC combinations)" and what Gabe calls "the percentage".
 *
 * ── Gabe's missing-pricing flow ────────────────────────────────────────────────────────
 *   "when I add a deal, that's it, it'll check the percentage. Look up the pricing, add it
 *    in there. If the pricing is not there, it tells you it's not there. So then we go to
 *    the investor price, like, oh, there's a new discount... it's a 27.9, and there is no
 *    BOS amount for that. They go to their pricing desk, do you want to add it? They'll put
 *    it in there... and then that way, we make it dynamic."
 *
 * So: missing pricing is surfaced on the deal, not hidden, and is fixable inline without
 * leaving the tranche you were building.
 */

import { num, round2 } from './calc.js';
import { getPricing, setPricing, addPricingRow } from './sandbox.js';

/**
 * Tax-credit tiers, named by the adders that produce them. Values are what CRM stores.
 *
 * Gabe asked for Domestic Content to appear alongside Energy Community, having built the
 * original CRM matrix before DC was in use. It is already here: the tax credit IS the
 * rubric (0.30 base + 0.10 EC + 0.10 DC), so DC is the 40% tier when it is the only adder
 * and the 50% tier together with EC. He reached the same conclusion reading the grid on
 * the call — "they are right… naming things a little off". So this is a naming fix, not a
 * new column. It could not be a new column: the CRM matrix has exactly five fixed rate
 * fields and adding a sixth is an admin schema change no widget can make.
 *
 * `short` is what the grid header shows; `rubric` is the full plain-English name.
 */
export const TAX_TIERS = [
  { value: 0.3, label: '.30', short: 'No adders', rubric: 'No adders — neither EC nor DC' },
  { value: 0.4, label: '.40', short: 'EC or DC', rubric: 'One adder — Energy Community OR Domestic Content' },
  { value: 0.5, label: '.50', short: 'EC + DC', rubric: 'Both adders — Energy Community + Domestic Content' },
];

/**
 * The standard prepay % of SOW at each tier, as Gabe gave them on the 2026-08-11 call:
 * "75 for the 50s, 80 for the 40s, and for the 30, 85". More tax credit ⇒ the investor
 * needs less prepay, which is the shape the observed Tranche-77 data already had.
 *
 * He noted these have since been negotiated lower in places; these are the standard book
 * rates, which is what he asked the demo to show. Cells matching one of these pairs are
 * tagged `standard` by the seeder so the grid can mark them as the ones actually in use.
 */
export const STANDARD_SOW = { 0.5: 0.75, 0.4: 0.8, 0.3: 0.85 };

/** Is this (SOW, tax) pair one of the three standard book rubrics? */
export const isStandardRubric = (sow, tax) => STANDARD_SOW[round2(tax)] === round2(sow);

/** The SOW percentages actually seen in production, as the starting grid. */
export const SOW_STEPS = [0.7, 0.73, 0.75, 0.78, 0.8, 0.83, 0.85];

const key = (sow, tax) => `${round2(sow)}|${round2(tax)}`;

/**
 * Seed matrix for a sample investor.
 *
 * Gabe, on how to get the real ones filled in:
 *   "We'll create a sample one for like, you know, solar demo investments, and then they'll
 *    be like, oh, okay, and this is how it works. Okay, stupid, go build the other one."
 *
 * Rates come from the real Tranche 77 pairs where we have them; the rest interpolate on the
 * same shape (BoS% rises as the tax credit falls, because the investor needs more prepay
 * when the ITC is smaller). Marked so nobody mistakes an interpolated cell for a real one.
 */
const OBSERVED = {
  '0.75|0.4': 0.6589,
  '0.7|0.5': 0.5905,
  '0.8|0.4': 0.6732,
  '0.83|0.3': 0.7403,
  '0.75|0.5': 0.625,
  '0.73|0.4': 0.6533,
  '0.78|0.4': 0.6689,
  '0.85|0.3': 0.7448,
  '0.73|0.5': 0.6083,
};

/** Same shape as the observed data: BoS% ≈ SOW/1.2, lifted as the tax credit drops. */
function modelled(sow, tax) {
  const base = sow / 1.2;
  const lift = tax === 0.5 ? 1.0 : tax === 0.4 ? 1.054 : 1.07;
  return round4(base * lift);
}

const round4 = (n) => Math.round(n * 1e4) / 1e4;

/**
 * Build the starter grid.
 * @param {object} [opts]
 * @param {number[]} [opts.omitTax]  tax tiers to leave UNPRICED — used to give a second
 *                                   investor a deliberate gap (Gabe: "missing pricing for
 *                                   50's, this way we can see if it filters that out").
 */
export function seedMatrix(opts = {}) {
  const omit = new Set(opts.omitTax ?? []);
  const tweak = opts.tweak ?? ((sow, tax, p) => p);
  const rows = [];
  for (const sow of SOW_STEPS) {
    for (const t of TAX_TIERS) {
      if (omit.has(t.value)) continue; // leave this tier unpriced on purpose
      const k = key(sow, t.value);
      const observed = OBSERVED[k];
      const base = observed ?? modelled(sow, t.value);
      rows.push({
        sow,
        tax: t.value,
        bosPct: round4(tweak(sow, t.value, base)),
        source: observed ? 'observed' : 'modelled',
        standard: isStandardRubric(sow, t.value),
      });
    }
  }
  return rows;
}

/** Default per-tranche fees the investor selector applies — Gabe: "which sets all the different fees, like a default". */
export const DEFAULT_FEES = [
  { label: 'Standard financing fee', amount: 0 },
  { label: 'Tax insurance', amount: 0 },
];

/**
 * Rows for an investor, creating the seed on first use.
 * The sample investor gets a populated grid; real investors start EMPTY, which is the
 * honest state — nobody has entered their pricing yet, and pretending otherwise would
 * hide exactly the gap this module exists to expose.
 */
export function matrixFor(investor) {
  const existing = getPricing(investor.id);
  // An EMPTY stored matrix (`[]`) is truthy — guard on length so a stale/empty persisted
  // matrix from an earlier session still re-seeds, instead of leaving every deal unpriced.
  if (existing && existing.length) return existing;
  // seedProfile drives the demo: 'full' = complete grid, 'gap50' = everything except the
  // 50% tier (the deliberate hole Gabe asked for). Anything else starts empty — the honest
  // state for a real investor whose pricing nobody has entered yet.
  let rows = [];
  if (investor.seedProfile === 'full' || investor.sample) {
    rows = seedMatrix();
  } else if (investor.seedProfile === 'gap50') {
    // The second investor: no 50% tier at all, and rates that cross over Power's — a bit
    // better (lower BoS% ⇒ higher investor contribution) at 40%, a bit worse at 30%. So
    // Maximise Margin genuinely splits deals between the two instead of always picking one.
    rows = seedMatrix({
      omitTax: [0.5],
      tweak: (sow, tax, p) => (tax === 0.4 ? p * 0.97 : tax === 0.3 ? p * 1.03 : p),
    });
  }
  setPricing(investor.id, rows);
  return rows;
}

/**
 * Populate an investor with the Tranche-77 starter grid. This is the answer to Gabe's
 * "where is the pricing matrix for these dudes?" — there is none in CRM, so this seeds one
 * he can then adjust per investor. Explicit (a button), never silent, and labelled as
 * derived-from-Tranche-77 so a starter cell is never mistaken for a real negotiated rate.
 */
export function loadStarterRates(investor) {
  const rows = seedMatrix();
  setPricing(investor.id, rows);
  return rows;
}

/** How much of an investor's matrix is real vs starter, for an honest status line. */
export function matrixStatus(investor) {
  const rows = getPricing(investor.id) ?? [];
  return {
    total: rows.length,
    entered: rows.filter((r) => r.source === 'entered').length,
    starter: rows.filter((r) => r.source !== 'entered').length,
    empty: rows.length === 0,
  };
}

/** The (SOW, tax-credit) cell a deal falls in. */
export function rubricFor(deal, taxCredit) {
  const sow = num(deal.Pre_Pay_Pct_of_Statement_of_Work);
  const tax = taxCredit ?? num(deal.Tax_Credit_Percentage);
  return { sow: sow === null ? null : round2(sow), tax: tax === null ? null : round2(tax) };
}

/**
 * Look up a deal's pricing. Returns null when the investor has no row for that rubric —
 * which is the whole point: "If the pricing is not there, it tells you it's not there."
 */
export function lookup(investor, deal, taxCredit) {
  const { sow, tax } = rubricFor(deal, taxCredit);
  if (sow === null || tax === null) return { row: null, sow, tax, reason: 'Deal has no SOW % or tax credit' };
  const rows = matrixFor(investor);
  const row = rows.find((r) => round2(r.sow) === sow && round2(r.tax) === tax) ?? null;
  return {
    row,
    sow,
    tax,
    reason: row ? null : `No pricing for ${(sow * 100).toFixed(1)}% SOW at ${(tax * 100).toFixed(0)}% tax credit`,
  };
}

/** Add a rate inline, without leaving the tranche you were building. */
export function addRate(investor, sow, tax, bosPct) {
  matrixFor(investor); // ensure the investor has a matrix before appending
  return addPricingRow(investor.id, {
    sow: round2(sow),
    tax: round2(tax),
    bosPct: round4(bosPct),
    source: 'entered',
  });
}

export function saveMatrix(investor, rows) {
  setPricing(investor.id, rows);
}

/**
 * Every rubric present in a set of deals but missing from the investor's matrix.
 * This is the "you cannot get it wrong" surface — it names precisely what is unpriced
 * rather than leaving someone to discover it deal by deal.
 */
export function gapsFor(investor, deals, taxCreditOf) {
  const gaps = new Map();
  for (const d of deals) {
    const { row, sow, tax } = lookup(investor, d, taxCreditOf?.(d));
    if (row || sow === null || tax === null) continue;
    const k = key(sow, tax);
    const g = gaps.get(k) ?? { sow, tax, count: 0 };
    g.count += 1;
    gaps.set(k, g);
  }
  return [...gaps.values()].sort((a, b) => b.count - a.count);
}

export const fmtPct = (n) => (n == null ? '—' : `${(n * 100).toFixed(2)}%`);
