/**
 * Live CRM queries.
 *
 * Every api_name and every WHERE clause here was run against the real org (663893953)
 * and returned rows. Things that looked obviously right and turned out NOT to be are
 * recorded in DO_NOT_QUERY below — that list is the valuable half of this file.
 *
 * Three COQL traps, all hit for real:
 *
 *  1. Module is `Tranches`. `FROM CustomModule8` returns INVALID_MODULE, even though
 *     CustomModule8 is what the record URLs and the metadata export use.
 *  2. A flat `WHERE A and B and C` is a SYNTAX_ERROR. Conditions must be parenthesised
 *     pairwise: `((A and B) and C)`.
 *  3. Lookups come back as bare `{id: "..."}` with no name. Resolve them with a second
 *     query rather than dot-notation, which is not confirmed to work here.
 */

import { coql } from './zoho.js';

/**
 * Names that LOOK right and are not. Each was tried live and returned INVALID_QUERY.
 * Selecting any one of these fails the ENTIRE query, so this list is load-bearing.
 */
export const DO_NOT_QUERY = {
  Tranche_Number: 'INVALID_QUERY on Deals. No Deals-side tranche ordinal exists.',
  Tranche_Date: 'Not on Deals — lives on Tranches. Query FROM Tranches.',
  Additional_Pre_Pay: 'Not a Deals field. It was a derived column in the Excel export.',
  Full_Electricity_Price: 'Not a Deals field.',
  Final_Inspection_Received: 'Dead field — real label is "XFinal Inspection Complete".',
  Final_Invoice: 'Dead field — real label is "XFinal Invoice Approved".',
  CustomModule8: 'Not a COQL module name. Use Tranches.',
  M1_Lite: 'Exists and is boolean, but only 3 true rows org-wide and all are test deals.',
};

/** Confirmed selectable on Deals. */
const DEAL_FIELDS = [
  'id', 'Deal_Name', 'Customer_State', 'Stage', 'Deal_Type',
  'Amount', 'System_Size', 'Battery_kW_Size',
  'Pre_Pay_Amount', 'Commitment_Fee', 'Prepay_with_Commitment_Fee',
  'Bill_of_Sale_Amount', 'Total_Investor_Contribution',
  'Pre_Pay_Pct_of_Statement_of_Work', 'Pre_Paid_Percentage_of_Bill_of_Sale',
  'Energy_Community_Tax_Eligible', 'Energy_Community_Title',
  'Domestic_Content', 'Tax_Credit_Percentage', 'ITC_Amount',
  'Permit_Status', 'Avail_for_Purchase', 'M1_Approved', 'NTP_Underwriting_Complete',
  'Account_Name', 'Tranche',
];

/**
 * The three pools.
 *
 * `Avail_for_Purchase = true` on its own is NOT the pool — it returns 625 rows spanning
 * Funded, Closed Lost and Transferred deals. Constraining to Stage 'M1' with no tranche
 * assigned gives 219, which is a believable working set.
 *
 * `Permit_Status` is the permit-vs-signed-job-card discriminator Gabe described. Its live
 * values are exactly "Permit", "Job Card Signed", "Final Affidavit", "PTO as final" — so
 * his "if it says permit, it's an M1 Lite" maps to a real field, not the `M1_Lite`
 * boolean (which is 3 test rows).
 */
export const POOL_QUERIES = {
  available: {
    label: 'M1 available for purchase',
    // "Prepped for sale" per Gabe — an M1 deal that's reached its M1 certificate OR is
    // explicitly flagged available, and isn't in a tranche yet. The old rule required only
    // the Avail_for_Purchase checkbox, which caught 7 of his ~60 prepped test deals because
    // most have M1_Approved (label "M1 Certificate Signed") set but not the checkbox.
    where: `(((Avail_for_Purchase = true or M1_Approved = true) and Stage = 'M1') and Tranche is null)`,
    confidence: 'PROVISIONAL — "prepped for sale" = M1 approved OR flagged available. Confirm the exact rule with Gabe.',
  },
  lite: {
    label: 'M1 lite',
    where: `((Permit_Status = 'Permit' and Stage = 'M1') and Tranche is null)`,
    confidence: 'PROVISIONAL — uses the real Permit_Status discriminator, count unverified',
  },
  soon: {
    label: 'Soon-to-be M1',
    // Every remaining M1 deal that isn't approved, available, or a permit-lite — so no test
    // deal falls through all three buckets. Permit deals dedup to lite (tested first).
    where: `(((Stage = 'M1' and M1_Approved = false) and Avail_for_Purchase = false) and Tranche is null)`,
    confidence: 'PROVISIONAL — catch-all for M1 not yet approved or available',
  },
};

/**
 * COQL caps a page at 200 rows, so anything bigger needs paging. The available pool is
 * ~219 and "soon-to-be" is larger, so a single call silently truncates — which looks
 * like a smaller pipeline rather than a bug.
 */
const PAGE = 200;
const MAX_ROWS = 1000; // sanity stop; the UI renders 60 and this is a review build

/**
 * Test-record filter. `Test_Record` is a real boolean on Deals — 18 test M1s already exist
 * ("Mctesty ...", "Jay Test ..."), and Gabe curates more for demos. finalizeTranche5 also
 * skips Test_Record deals, so this is the same flag the platform uses to keep test and
 * real data apart.
 *
 *   all  — no filter
 *   test — only test records (the clean, curated demo set)
 *   real — exclude test records
 */
export const TEST_MODES = {
  all: { label: 'All deals', clause: null },
  test: { label: 'Test records only', clause: 'Test_Record = true' },
  real: { label: 'Exclude test', clause: 'Test_Record = false' },
};

async function fetchAll(where, testClause) {
  // `where` is already fully parenthesised; one more AND condition wraps cleanly.
  const full = testClause ? `(${where} and ${testClause})` : where;
  const rows = [];
  for (let offset = 0; offset < MAX_ROWS; offset += PAGE) {
    const page =
      `select ${DEAL_FIELDS.join(',')},Test_Record from Deals where ${full} ` +
      `limit ${PAGE} offset ${offset}`;
    const { rows: got } = await coql(page);
    rows.push(...got);
    if (got.length < PAGE) break; // short page ⇒ last page
  }
  return rows;
}

/**
 * Fetch all three pools and tag each row with the pool it came from.
 *
 * Queried separately rather than as one OR: the pools are defined by different fields,
 * an OR across them re-introduces the overlap problem, and a failure in one pool
 * shouldn't blank the other two.
 */
export async function loadLiveDeals(testMode = 'all') {
  const out = [];
  const perPool = {};
  const testClause = TEST_MODES[testMode]?.clause ?? null;

  for (const [key, def] of Object.entries(POOL_QUERIES)) {
    try {
      const rows = await fetchAll(def.where, testClause);
      perPool[key] = rows.length;
      for (const r of rows) out.push({ ...r, __pool: key });
    } catch (e) {
      perPool[key] = `failed: ${e?.message || e}`;
      console.warn(`pool "${key}" query failed`, e);
    }
  }

  // A deal can satisfy more than one pool. Permit wins, matching Gabe's double filter.
  const seen = new Map();
  const order = ['lite', 'available', 'soon'];
  for (const key of order) {
    for (const d of out.filter((x) => x.__pool === key)) {
      if (!seen.has(d.id)) seen.set(d.id, d);
    }
  }
  const deals = [...seen.values()];

  await resolveInstallers(deals);
  return { deals, perPool };
}

/**
 * COQL returns `Account_Name` as `{id}` with no name. One extra query resolves them all
 * rather than N lookups, and a failure here only costs us the installer label.
 */
async function resolveInstallers(deals) {
  const ids = [...new Set(deals.map((d) => d.Account_Name?.id).filter(Boolean))];
  if (!ids.length) return;

  // An `id in (...)` list of 100 returns "value limit exceeded" — Zoho caps the number of
  // values in an IN clause well below that. 25 per query is comfortably under it.
  const CHUNK = 25;
  const byId = new Map();
  for (let i = 0; i < ids.length; i += CHUNK) {
    const chunk = ids.slice(i, i + CHUNK);
    try {
      const { rows } = await coql(
        `select id, Account_Name from Accounts ` +
          `where id in (${chunk.map((x) => `'${x}'`).join(',')}) limit 200`
      );
      for (const r of rows) byId.set(String(r.id), r.Account_Name);
    } catch (e) {
      // A missing installer label must not cost us the deal row.
      console.warn(`installer chunk ${i / CHUNK} failed`, e);
    }
  }

  for (const d of deals) {
    const id = d.Account_Name?.id;
    d.Account_Name = id ? (byId.get(String(id)) ?? '(installer not resolved)') : null;
  }
}

/**
 * Investors live in the dedicated `Investor` module — NOT Accounts.
 *
 * This matters: `Investor_Pricing.Investor` is a lookup to the `Investor` module, so the
 * pricing lookup only matches when we list investors from HERE. Accounts has a PARALLEL
 * Account_Type='Investor' set, but its record ids do not match the pricing records — listing
 * from Accounts (the old behaviour) meant Live-mode pricing NEVER resolved and every deal read
 * "No pricing". The `Investor` record links to its price sheet via `Product_Pricing` and,
 * optionally, back to an Account via `Account` (frequently null — e.g. Bayshore's is unset).
 */
export async function loadLiveInvestors() {
  const { rows } = await coql(
    `select id, Name from Investor where Name is not null order by Name limit 200`
  );
  return rows;
}

/** Recent tranches. Module is `Tranches`; `Tranche_Pricing` is null on every 2026 record. */
export async function loadLiveTranches() {
  const { rows } = await coql(
    `select id, Name, Tranche_Status, Tranche_Date, Tranche_Pricing, Investor ` +
      `from Tranches where Tranche_Date is not null ` +
      `order by Tranche_Date desc limit 6`
  );
  return rows;
}

/**
 * Every OPEN tranche, newest first — the set the switcher offers.
 *
 * Separate from loadLiveTranches (which caps at 6 for the Recent strip) because this one
 * has to be complete: they run several open tranches at once, split per installer, and a
 * truncated list silently hides one. `Investor` comes back as a bare `{id}`; the caller
 * matches it against the already-loaded investor list rather than paying a second query.
 */
export async function loadLiveOpenTranches() {
  const rows = [];
  for (let offset = 0; offset < 600; offset += PAGE) {
    const { rows: got } = await coql(
      `select id, Name, Tranche_Status, Tranche_Date, Investor ` +
        `from Tranches where Tranche_Status = 'Open' ` +
        `order by Tranche_Date desc limit ${PAGE} offset ${offset}`
    );
    rows.push(...got);
    if (got.length < PAGE) break;
  }
  return rows;
}

/**
 * The deals already assigned to a tranche.
 *
 * Paged, deliberately. The CRM button that fills the System Schedule subform
 * (`trancheBtn_updtTotals1`) reads its deals with a single un-paginated
 * `zoho.crm.searchRecords`, which returns at most 200 and then silently stops — so a big
 * tranche gets a short document with no error. This widget must not inherit that: if a
 * tranche really holds 300 deals we want to SEE 300 here, so the count disagrees loudly
 * with whatever the subform shows.
 */
export async function loadLiveTrancheDeals(trancheId) {
  const rows = [];
  for (let offset = 0; offset < MAX_ROWS; offset += PAGE) {
    const { rows: got } = await coql(
      `select ${DEAL_FIELDS.join(',')},Test_Record from Deals ` +
        `where Tranche = '${String(trancheId)}' limit ${PAGE} offset ${offset}`
    );
    rows.push(...got);
    if (got.length < PAGE) break;
  }
  await resolveInstallers(rows);
  return rows;
}
