/**
 * Read the REAL investor pricing from CRM.
 *
 * The pricing matrix is not invented — it lives in the `Investor_Pricing` module (one
 * record per investor per year, ~26 populated) with an `Investor_Pricing_Matrix` subform.
 * Verified against the live record "2024 - Bayshore Energy 1 LLC". Shape:
 *
 *   Investor_Pricing:
 *     Investor (lookup → Account), Pricing_Year "2024", Investor_Pricing_Status "Active",
 *     Corrient_Fee / Corrient_Fee_EC (the fees), Energy_Community, M1_Light_Eligible,
 *     Investor_Pricing_Matrix (subform), Deployment_Schedule (subform)
 *
 *   Investor_Pricing_Matrix — one row per (State × HDM_Product):
 *     State: "CA" | "TX" | "NV" | "OK" | ...
 *     HDM_Product: "PPA" | "PPA Combo" | "ESSA"
 *     rate columns, named (SOW/tax-credit), value = the Bill-of-Sale %:
 *       EC_Pricing_75_40   0.655   (SOW 75%, 40% credit, energy-community)
 *       EC_Pricing_76_40   0.665
 *       EC_Pricing_77_40   0.665
 *       EC_Pricing_pend_50 0       (50% tier — pending/unpriced: a real gap)
 *       Non_EC_Pricing_80_30 0.725 (SOW 80%, 30% credit, NOT energy-community)
 *
 * So the real key is (State, Product, SOW %, tax-credit %, EC-or-not) → Bill-of-Sale %.
 * That confirms the widget's (SOW × tax) rubric and adds State + Product + the EC split.
 *
 * Subforms don't come through COQL, so we COQL the parent for its id, then getRecord to
 * pull the subform inline (ZOHO.CRM.API.getRecord returns resp.data[0] with subforms).
 */

import { coql, sdk } from './zoho.js';
import { num } from './calc.js';

/** Deal_Type → HDM_Product. INFERRED mapping — confirm with Gabe. */
export function productFor(deal) {
  const t = String(deal.Deal_Type ?? '').toLowerCase();
  if (t.includes('solar with storage')) return 'PPA Combo';
  if (t.includes('storage')) return 'ESSA';
  return 'PPA'; // Residential/Commercial Solar
}

/**
 * The rate columns, decoded into (SOW, tax, EC) points. Value 0 means the cell is unpriced
 * (a real gap — e.g. the pending 50% tier), so we drop zeros.
 *
 * IMPORTANT: this is the COMPLETE set. Verified live (2026-07-31) across three Active
 * Investor_Pricing records: the matrix subform has exactly these five rate columns and no
 * others. So only these five (SOW, tax, EC) combinations are representable in CRM — an
 * arbitrary rate a user types cannot be stored unless it lands on one of them. Adding a new
 * column is a CRM schema change (admin, in Setup), not something a widget can do.
 */
export const COLUMNS = [
  { col: 'EC_Pricing_75_40', sow: 0.75, tax: 0.4, ec: true, label: '75% SOW · 40% credit · Energy Community' },
  { col: 'EC_Pricing_76_40', sow: 0.76, tax: 0.4, ec: true, label: '76% SOW · 40% credit · Energy Community' },
  { col: 'EC_Pricing_77_40', sow: 0.77, tax: 0.4, ec: true, label: '77% SOW · 40% credit · Energy Community' },
  { col: 'EC_Pricing_pend_50', sow: null, tax: 0.5, ec: true, label: '50% credit tier (SOW pending) · Energy Community' },
  { col: 'Non_EC_Pricing_80_30', sow: 0.8, tax: 0.3, ec: false, label: '80% SOW · 30% credit · not Energy Community' },
];

/** The named CRM cell a (SOW, tax, EC) rubric maps to, or null if CRM cannot store it. */
export function columnForRubric(sow, tax, ec) {
  return (
    COLUMNS.find(
      (c) =>
        c.ec === !!ec &&
        Math.abs(c.tax - tax) < 1e-9 &&
        // pend_50 is SOW-agnostic; the others must match SOW to the whole percent.
        (c.sow == null || (sow != null && Math.abs(c.sow - sow) < 5e-3))
    ) ?? null
  );
}

export const PRODUCTS = ['PPA', 'PPA Combo', 'ESSA'];

/** Flatten a subform row into normalized rate entries. */
function expandRow(row) {
  const out = [];
  for (const c of COLUMNS) {
    const v = num(row[c.col]);
    if (!v || v <= 0) continue; // 0 / null = unpriced cell
    out.push({ state: row.State, product: row.HDM_Product, sow: c.sow, tax: c.tax, ec: c.ec, bosPct: v });
  }
  return out;
}

/**
 * Load an investor's real pricing, or report there is none.
 * @returns {Promise<{found:boolean, recordId?, year?, fees?, rates?, states?, products?}>}
 */
export async function loadInvestorPricing(accountId) {
  // 1. Find the investor's Active pricing record — prefer the latest year.
  let rec;
  try {
    const { rows } = await coql(
      `select id, Pricing_Year, Corrient_Fee, Corrient_Fee_EC ` +
        `from Investor_Pricing where (Investor = '${accountId}' and Investor_Pricing_Status = 'Active') ` +
        `limit 10`
    );
    if (!rows.length) return { found: false };
    // Highest year wins; null years sort last.
    rows.sort((a, b) => String(b.Pricing_Year ?? '').localeCompare(String(a.Pricing_Year ?? '')));
    rec = rows[0];
  } catch (e) {
    console.warn('investor pricing lookup failed', e);
    return { found: false, error: e?.message || String(e) };
  }

  // 2. Pull the full record for its matrix subform.
  let full;
  try {
    const ZOHO = await sdk();
    const resp = await ZOHO.CRM.API.getRecord({ Entity: 'Investor_Pricing', RecordID: String(rec.id) });
    full = resp?.data?.[0];
  } catch (e) {
    console.warn('investor pricing getRecord failed', e);
    return { found: false, error: e?.message || String(e) };
  }
  if (!full) return { found: false };

  const subform = full.Investor_Pricing_Matrix ?? [];
  const rates = subform.flatMap(expandRow);
  return {
    found: rates.length > 0,
    recordId: String(rec.id),
    year: full.Pricing_Year ?? rec.Pricing_Year ?? null,
    fees: { corrient: num(full.Corrient_Fee), corrientEC: num(full.Corrient_Fee_EC) },
    rates,
    states: [...new Set(rates.map((r) => r.state))].sort(),
    products: [...new Set(rates.map((r) => r.product))].sort(),
    rowCount: subform.length,
  };
}

/**
 * Look up a deal's Bill-of-Sale % in a loaded real matrix.
 * Matches State + Product, then the (tax, EC) group, then the nearest SOW within it.
 * Returns null when the investor has no rate for that rubric — a genuine gap, which the UI
 * surfaces rather than papering over (Gabe: "the tool don't work if no investor pricing").
 */
export function lookupLive(pricing, deal, taxTier, isEC) {
  if (!pricing?.rates?.length) return null;
  const state = deal.Customer_State;
  const product = productFor(deal);
  const dealSow = num(deal.Pre_Pay_Pct_of_Statement_of_Work);

  const candidates = pricing.rates.filter(
    (r) =>
      r.state === state &&
      r.product === product &&
      Math.abs(r.tax - taxTier) < 1e-9 &&
      r.ec === isEC
  );
  if (!candidates.length) return null;

  // Pick the row whose SOW is closest to the deal's (a null-SOW column, e.g. pending/50,
  // matches anything in its tier).
  let best = candidates[0];
  if (dealSow != null) {
    let bestGap = Infinity;
    for (const c of candidates) {
      const gap = c.sow == null ? 0.001 : Math.abs(c.sow - dealSow);
      if (gap < bestGap) { bestGap = gap; best = c; }
    }
  }
  return { bosPct: best.bosPct, matchedSow: best.sow, state, product, source: 'crm' };
}
