/** Does this investor have any pricing at all? — the gate for showing it in the dropdown. */
function investorHasPricing(i) {
  return !!(i.livePricing?.found || i.sample || i.seedProfile || matrixStatus(i).total > 0);
}

function renderHead() {
  const inv = investor();
  const sel = $('#investor');
  sel.innerHTML = '';
  // Gabe: "the dropdown on the investors should not appear if it doesn't have a pricing
  // matrix." Show only investors that have pricing — but never render an empty dropdown, and
  // always keep the currently-selected one visible.
  // Sandbox: only investors that have a pricing matrix (both demo investors do). Live: show
  // EVERY real investor — the full book is wanted even before their pricing is entered.
  let list = mode.isSandbox ? S.investors.filter(investorHasPricing) : S.investors.slice();
  if (!list.length) list = S.investors.slice();
  if (S.investorId && !list.some((i) => i.id === S.investorId)) {
    const cur = S.investors.find((i) => i.id === S.investorId);
    if (cur) list = [cur, ...list];
  }
  // Alphabetical by investor name so the dropdown is easy to scan.
  list.sort((a, b) => String(a.Account_Name || '').localeCompare(String(b.Account_Name || '')));
  const hidden = S.investors.length - list.length;
  for (const i of list) {
    const o = el('option', '', i.Account_Name + (i.real ? '' : '  [sample]'));
    o.value = i.id;
    if (i.id === S.investorId) o.selected = true;
    sel.append(o);
  }
  $('#targetLock').value = S.targetLock;
  renderOpenTranches();
  const parts = [];
  if (inv?.note) parts.push(inv.note);
  if (hidden > 0) parts.push(`${hidden} investor${hidden > 1 ? 's' : ''} hidden — no pricing matrix yet.`);
  $('#invNote').textContent = parts.join('  ·  ');
}

/**
 * Every open tranche this investor has going, from both sources: the real ones in CRM and
 * the ones created in this sandbox session. Newest first.
 *
 * Gabe's use case is the reason this has to be complete rather than recent: they run
 * several open tranches at once — M1 Light split per installer — and jump between them.
 * "We need a section where we can see open tranches for that particular investor, so we
 * can say well, we're gonna put this one for this day, then for that date."
 */
function openTrancheChoices() {
  const inv = investor();
  const fromSandbox = sandbox.sandbox.tranches
    .filter((t) => t.status === 'Open' && (!inv || t.investorName === inv.Account_Name))
    .map((t) => ({
      id: t.id,
      date: String(t.createdAt).slice(0, 10),
      name: t.name,
      dealCount: t.dealIds.length,
      source: 'sandbox',
    }));
  // Real CRM tranches match on the Investor lookup id. Sample-mode rows carry no investor
  // id at all, so they show against whoever is selected — they only exist for local dev.
  const fromCrm = S.openTranches
    .filter((t) => !inv || !t.investorId || String(t.investorId) === String(inv.id))
    .map((t) => ({ ...t, source: 'crm' }));

  const all = [...fromSandbox, ...fromCrm];
  const q = (S.openSearch || '').trim().toLowerCase();
  const matched = q
    ? all.filter((t) => `${t.name ?? ''} ${t.date ?? ''}`.toLowerCase().includes(q))
    : all;
  matched.sort((a, b) => String(b.date ?? '').localeCompare(String(a.date ?? '')));
  return { matched, total: all.length };
}

/**
 * Find a tranche by id across every source, ignoring the investor and search filters.
 * Used when opening one — see openTrancheIntoBuilder.
 */
function findTrancheChoice(id) {
  const want = String(id);
  const sbx = sandbox.sandbox.tranches.find((t) => String(t.id) === want);
  if (sbx) {
    return {
      id: sbx.id,
      date: String(sbx.createdAt).slice(0, 10),
      name: sbx.name,
      dealCount: sbx.dealIds.length,
      investorId: sbx.investorId,
      source: 'sandbox',
    };
  }
  const crm = S.openTranches.find((t) => String(t.id) === want);
  return crm ? { ...crm, source: 'crm' } : null;
}

/** The open-tranche picker: this investor's Open tranches, plus "New tranche" (default). */
function renderOpenTranches() {
  const sel = $('#openTranche');
  if (!sel) return;
  const { matched, total } = openTrancheChoices();

  if (S.openTrancheId !== 'new' && !matched.some((t) => String(t.id) === String(S.openTrancheId))) {
    // The selection fell out of the filtered list (investor changed, or the search hid it).
    // Keep it visible rather than silently switching what's loaded underneath them.
    const loaded = S.loadedTranche;
    if (loaded && String(loaded.id) === String(S.openTrancheId)) {
      matched.unshift({ id: loaded.id, date: loaded.date, name: loaded.name, dealCount: loaded.dealCount, source: loaded.source });
    } else {
      S.openTrancheId = 'new';
    }
  }

  sel.innerHTML = '';
  const nw = el('option', '', '＋ New tranche');
  nw.value = 'new';
  if (S.openTrancheId === 'new') nw.selected = true;
  sel.append(nw);
  for (const t of matched) {
    const count = t.dealCount == null ? '' : ` · ${t.dealCount} deal${t.dealCount === 1 ? '' : 's'}`;
    const label = `${t.date || '(no date)'}${count}${t.source === 'sandbox' ? '  [sandbox]' : ''} — ${t.name ?? 'Tranche'}`;
    const o = el('option', '', label);
    o.value = String(t.id);
    if (String(t.id) === String(S.openTrancheId)) o.selected = true;
    sel.append(o);
  }

  const cnt = $('#openCount');
  if (cnt) {
    const q = (S.openSearch || '').trim();
    cnt.textContent = !total
      ? 'no open tranches'
      : q ? `${matched.length} of ${total}` : `${total} open`;
  }
}

/**
 * Load an existing open tranche into the builder — the "build into an existing tranche"
 * half of the switcher, as opposed to just looking at it.
 *
 * Its deals come back from CRM and go straight into the working list, so adding, dropping
 * and re-dating happen in exactly the same place as they do for a new tranche. The deals
 * are merged into S.deals first because they are NOT in any pool (every pool query requires
 * `Tranche is null`), and pickedRows() resolves ids against S.deals.
 *
 * Editing is gated to test records — Trevor's call, 2026-08-11. A real tranche opens
 * read-only: you can see exactly what's in it, and nothing you do writes to CRM.
 */
async function openTrancheIntoBuilder(id) {
  // Look the tranche up across EVERY source, unfiltered. openTrancheChoices() is scoped to
  // the selected investor, but the bottom strip can open a tranche belonging to a different
  // one — and resolving it against the filtered list would silently return undefined, so it
  // would load with no name, no date, and priced under the wrong investor's matrix.
  const choice = findTrancheChoice(id);
  S.openTrancheId = String(id);
  S.loadingTranche = true;

  // Follow the tranche to its investor. Pricing is per-investor, so leaving the selector on
  // someone else would value every deal in this tranche against the wrong rate sheet.
  if (choice?.investorId && String(choice.investorId) !== String(S.investorId)) {
    const target = S.investors.find((i) => String(i.id) === String(choice.investorId));
    if (target) {
      S.investorId = target.id;
      S.feeBlanket = 0;
      S.feeOverrides = {};
      await ensureInvestorPricing(target);
    }
  }
  render();

  try {
    let deals;
    if (choice?.source === 'sandbox') {
      const t = sandbox.sandbox.tranches.find((x) => String(x.id) === String(id));
      deals = (t?.dealIds ?? []).map((did) => S.deals.find((d) => d.id === did)).filter(Boolean);
    } else {
      deals = await loadTrancheDeals(id);
      // Merge into the deal set so the working list can resolve them. Replace rather than
      // duplicate — a deal could already be loaded from a pool in an earlier session state.
      const byId = new Map(S.deals.map((d) => [String(d.id), d]));
      for (const d of deals) byId.set(String(d.id), d);
      S.deals = [...byId.values()];
    }

    const allTest = deals.length > 0 && deals.every((d) => d.Test_Record === true);
    S.picked = new Set(deals.map((d) => d.id));
    S.feeBlanket = 0;
    S.feeOverrides = {};
    if (choice?.date) S.targetLock = choice.date;
    S.loadedTranche = {
      id: String(id),
      name: choice?.name ?? 'Tranche',
      date: choice?.date ?? null,
      dealCount: deals.length,
      source: choice?.source ?? 'crm',
      // What it held when opened — the baseline the save delta is computed against.
      originalDealIds: deals.map((d) => String(d.id)),
      originalDate: choice?.date ?? null,
      // Sandbox tranches are always editable. A CRM tranche is editable only when every
      // deal in it is a test record — the same guard createTrancheLive enforces on write.
      editable: choice?.source === 'sandbox' || allTest,
      allTest,
    };
  } catch (e) {
    console.warn('open tranche load failed', e);
    S.loadedTranche = { id: String(id), name: choice?.name ?? 'Tranche', error: e?.message || String(e), editable: false };
  } finally {
    S.loadingTranche = false;
    render();
  }
}

/**
 * Warn before throwing away unsaved work in the builder — an un-created draft, or edits to
 * a loaded tranche that were never applied. Returns true when it is safe to proceed.
 */
function confirmDiscard() {
  const t = S.loadedTranche;
  if (t && !t.error) {
    const d = trancheDelta();
    if (!d.dirty) return true;
    return window.confirm(`${t.name} has unsaved changes (${d.summary}). Discard them?`);
  }
  if (!S.picked.size) return true;
  return window.confirm(
    `${S.picked.size} deal${S.picked.size === 1 ? '' : 's'} in the draft tranche haven't been saved. Discard them?`
  );
}

/** Clear whatever tranche is loaded and go back to building a fresh one. */
function resetToNewTranche() {
  S.picked.clear();
  S.feeBlanket = 0;
  S.feeOverrides = {};
  S.openTrancheId = 'new';
  S.loadedTranche = null;
  S.activeTranche = null;
}

/**
 * The banner under the header saying what is loaded and whether it can be changed.
 *
 * This is the honest bit: on a real tranche it says plainly that nothing here writes to
 * CRM, so nobody discovers that by clicking Save and watching it fail.
 */
function renderLoadedBanner() {
  const box = $('#loadedBanner');
  if (!box) return;
  const t = S.loadedTranche;

  if (S.loadingTranche) {
    box.hidden = false;
    box.className = 'loaded-banner info';
    box.textContent = 'Loading tranche…';
    return;
  }
  if (!t) { box.hidden = true; box.innerHTML = ''; return; }

  box.hidden = false;
  box.innerHTML = '';

  if (t.error) {
    box.className = 'loaded-banner warn';
    box.append(el('span', '', `Couldn’t open ${t.name}: ${t.error}`));
  } else if (t.editable) {
    box.className = 'loaded-banner ok';
    box.append(el('strong', '', `Building into ${t.name}. `));
    box.append(el('span', '', `${t.dealCount} deal${t.dealCount === 1 ? '' : 's'} loaded — add or remove below, change the date above.`));
  } else {
    box.className = 'loaded-banner warn';
    box.append(el('strong', '', `${t.name} — read-only. `));
    box.append(el('span', '', `${t.dealCount} deal${t.dealCount === 1 ? '' : 's'} loaded so you can see exactly what's in it. ` +
      'It holds real (non-test) deals, so nothing here writes to CRM.'));
  }

  const back = el('button', 'mini', 'Back to new tranche');
  back.onclick = () => { resetToNewTranche(); render(); };
  box.append(back);
}

/** Is the builder currently accepting changes? False while a read-only tranche is loaded. */
const builderEditable = () => !S.loadedTranche || S.loadedTranche.editable === true;

/**
 * What has changed since the loaded tranche was opened — which deals joined, which left,
 * and whether the date moved. Drives both the Update button's enabled state and the
 * confirmation that spells the change out before it is applied.
 */
function trancheDelta() {
  const t = S.loadedTranche;
  if (!t) return { dirty: false, added: [], removed: [], dateChanged: false, summary: 'no changes' };

  const before = new Set((t.originalDealIds ?? []).map(String));
  const now = new Set([...S.picked].map(String));
  const added = [...now].filter((id) => !before.has(id));
  const removed = [...before].filter((id) => !now.has(id));
  const dateChanged = !!(t.originalDate && S.targetLock && t.originalDate !== S.targetLock);

  const bits = [];
  if (added.length) bits.push(`+${added.length} deal${added.length === 1 ? '' : 's'}`);
  if (removed.length) bits.push(`−${removed.length} deal${removed.length === 1 ? '' : 's'}`);
  if (dateChanged) bits.push(`date → ${S.targetLock}`);

  return {
    dirty: added.length > 0 || removed.length > 0 || dateChanged,
    added, removed, dateChanged,
    summary: bits.length ? bits.join(', ') : 'no changes',
  };
}

/**
 * The Key — plain-English documentation of every equation and every piece of logic, on the
 * page. Built once; the header "Key" button toggles it. Content comes from key.js, the single
 * source of truth kept in step with calc.js.
 */
let keyBuilt = false;
function renderKey() {
  const panel = $('#keyPanel');
  if (!panel || keyBuilt) return;
  keyBuilt = true;

  panel.append(el('div', 'key-intro', KEY_INTRO));

  const grid = el('div', 'key-grid');
  for (const f of FORMULAS) {
    const card = el('div', `key-card${f.flag ? ' key-flag' : ''}`);
    card.append(el('div', 'key-name', f.name));
    card.append(el('code', 'key-eq', f.equation));
    card.append(el('div', 'key-plain', f.plain));
    if (f.flag) {
      const w = el('div', 'key-warn');
      w.append(el('span', 'key-warn-badge', '⚠ heads up'));
      w.append(el('span', '', f.flag));
      card.append(w);
    }
    card.append(el('div', 'key-src', f.source));
    grid.append(card);
  }
  panel.append(grid);

  const pricing = el('div', 'key-block');
  pricing.append(el('div', 'key-name', 'Where the Bill-of-Sale % comes from'));
  pricing.append(el('div', 'key-plain', PRICING_KEY));
  panel.append(pricing);

  const legends = el('div', 'key-legends');
  const tagBlock = el('div', 'key-block');
  tagBlock.append(el('div', 'key-name', 'Deal tags'));
  for (const t of TAG_LEGEND) {
    const r = el('div', 'key-legend-row');
    r.append(el('span', `tag ${t.key}`, t.label), el('span', '', t.text));
    tagBlock.append(r);
  }
  const srcBlock = el('div', 'key-block');
  srcBlock.append(el('div', 'key-name', 'Where a number comes from'));
  for (const s of SOURCE_LEGEND) {
    const r = el('div', 'key-legend-row');
    r.append(el('span', `trace-src src-${s.key}`, s.label), el('span', '', s.text));
    srcBlock.append(r);
  }
  legends.append(tagBlock, srcBlock);
  panel.append(legends);
}

/** Show/hide the on-page Key. */
function toggleKey() {
  const panel = $('#keyPanel');
  const btn = $('#key');
  if (!panel) return;
  const collapsed = panel.classList.toggle('collapsed');
  if (btn) btn.textContent = collapsed ? '▸ Key' : '▾ Key';
}

/** Are the create/lock/price/swap actions available? Only in sandbox mode. */
const actionsOn = () => mode.isSandbox;
/** An action is permitted only when the role allows it AND we're in sandbox mode. */
const may = (role, cap) => actionsOn() && can(role, cap);
/** Why an action is blocked — live-mode message wins, since it applies to everyone. */
const whyBlocked = (role, cap) =>
  !actionsOn() ? 'Live mode is read-only — switch to Sandbox to make changes'
  : (denyReason(role, cap) || '');

/**
 * The Sandbox ⇄ Live switch. One control sets both what you see and what you can touch:
 *   Sandbox = test deals, everything interactive (Gabe plays).
 *   Live    = real deals, read-only (the team looks).
 */
function renderModeSwitch() {
  const box = $('#testFilter');
  if (!box) return;
  box.innerHTML = '';

  const swap = async (v) => {
    if (mode.value === v) return;
    mode.set(v);
    // Sandbox defaults to Gabe's mctesty set; live starts unfiltered.
    S.nameFilter = v === 'sandbox' && isLive() ? 'mctesty' : '';
    // The investor list differs by mode — sandbox = the two demo investors, live = the whole
    // real book — so reload investors too, not just deals, or Live keeps showing the demo two.
    [S.deals, S.investors] = await Promise.all([loadDeals(), loadInvestors()]);
    S.investorId = S.investors[0]?.id ?? null;
    S.picked.clear();
    S.feeBlanket = 0;
    S.feeOverrides = {};
    S.openTrancheId = 'new';
    render();                              // paint immediately…
    await ensureInvestorPricing(investor());
    render();                              // …then re-paint once the selected investor's pricing loads
  };

  const seg = el('div', 'modeswitch');
  const sb = el('button', `mode-opt ${mode.isSandbox ? 'active sandbox' : ''}`, 'Sandbox');
  sb.title = 'Test deals only · every action works · nothing touches CRM';
  sb.onclick = () => swap('sandbox');
  const lv = el('button', `mode-opt ${!mode.isSandbox ? 'active live' : ''}`, 'Live');
  lv.title = 'Real deals · read-only · look but don\'t touch';
  lv.onclick = () => swap('live');
  seg.append(sb, lv);
  box.append(seg);

  // Deal-name filter — a controlled population, Gabe's "dealname.contains mctesty".
  const nameWrap = el('label', 'namefilter');
  nameWrap.append(el('span', '', 'Name contains'));
  const inp = el('input');
  inp.type = 'search';
  inp.placeholder = 'e.g. mctesty';
  inp.value = S.nameFilter;
  // Re-filter only on click-away / Enter, not on every keystroke (per-character was jumpy).
  inp.onchange = (e) => { S.nameFilter = e.target.value; render(); };
  nameWrap.append(inp);
  box.append(nameWrap);

  const note = el('span', 'mode-note');
  const nf = (S.nameFilter || '').trim();
  note.textContent = mode.isSandbox
    ? `Sandbox — test deals${nf ? ` named “${nf}”` : ''}. Create, lock and pricing all work here; nothing is written to CRM.`
    : `Live — real deals${nf ? ` named “${nf}”` : ''}, read-only. Actions are turned off.`;
  note.classList.add(mode.isSandbox ? 'sandbox' : 'live');
  box.append(note);
}

function renderPools() {
  const bar = $('#pools');
  bar.innerHTML = '';
  bar.append(el('span', 'lbl', 'Pool:'));
  for (const p of POOLS) {
    const n = dealsInPool(p.key).length;
    const b = el('button', `pool ${S.pool === p.key ? 'active' : ''}`, `${p.label} · ${n}`);
    // Hover shows the full criteria; clicking also pins it in the panel below.
    b.title = `${p.label}\n\nCriteria:\n• ${(p.criteria ?? [p.hint]).join('\n• ')}`;
    b.onclick = () => { S.pool = p.key; render(); };
    bar.append(b);
  }
  renderCriteria();
}

/**
 * The active pool's full criteria, always visible under the tabs — the "show me what these
 * jobs are" ask. Plain-English rules, the exact live COQL, the confidence, and what the
 * pool actually returned last fetch (so a 0 is explainable, not mysterious).
 */
function renderCriteria() {
  const box = $('#criteria');
  if (!box) return;
  const c = poolCriteria(S.pool);
  box.innerHTML = '';

  const head = el('div', 'crit-head');
  head.append(el('span', 'crit-title', c.label));
  const count = el('span', 'crit-count');
  if (c.countError) count.textContent = `query failed`;
  else if (c.count !== null) count.textContent = `${c.count} in CRM${mode.isSandbox ? ' (test only)' : ''}`;
  else count.textContent = c.live ? '' : 'sample data';
  head.append(count);
  box.append(head);

  const list = el('ul', 'crit-list');
  for (const rule of c.criteria) list.append(el('li', '', rule));
  box.append(list);

  if (c.coql && c.live) {
    const coql = el('div', 'crit-coql');
    coql.append(el('span', 'crit-coql-lbl', 'Live filter'));
    coql.append(el('code', '', `WHERE ${c.coql}`));
    box.append(coql);
  }
  if (c.confidence) {
    const conf = el('div', 'crit-conf');
    conf.textContent = c.confidence;
    conf.classList.add(/verified/i.test(c.confidence) ? 'verified' : 'provisional');
    box.append(conf);
  }
}

function renderPoolTable() {
  const pool = POOLS.find((p) => p.key === S.pool);
  const all = dealsInPool(S.pool);
  const list = visibleDeals();

  const states = [...new Set(all.map((d) => d.Customer_State))].sort();
  const fbox = $('#filters');
  fbox.innerHTML = '';
  for (const st of states) {
    const on = S.stateFilter.has(st);
    const b = el('button', `pool ${on ? 'active' : ''}`, st);
    b.onclick = () => { on ? S.stateFilter.delete(st) : S.stateFilter.add(st); render(); };
    fbox.append(b);
  }
  $('#shown').textContent = `${list.length} of ${all.length} shown`;

  const body = $('#poolBody');
  body.innerHTML = '';

  // Only subdivide when the data can actually answer "has a final". On live records no
  // field is confirmed to mean that, and splitting anyway would label every deal wrongly.
  const groups =
    pool.subdivide && canSubdivide(list)
      ? [
          { label: 'Has a final', items: list.filter(hasFinal) },
          { label: 'No final yet', items: list.filter((d) => !hasFinal(d)) },
        ]
      : [{ label: null, items: list }];

  let rendered = 0;
  for (const g of groups) {
    if (!g.items.length) continue;
    if (g.label) {
      const tr = el('tr');
      const td = el('td', 'grouphdr', g.label);
      td.colSpan = 5;
      tr.append(td);
      body.append(tr);
    }
    for (const d of g.items.slice(0, 60)) { body.append(dealRow(d)); rendered += 1; }
  }
  if (!rendered) {
    const tr = el('tr');
    const td = el('td', 'empty', 'No deals match this pool and filter.');
    td.colSpan = 5;
    tr.append(td);
    body.append(tr);
  }
  const more = list.length - Math.min(list.length, 60);
  $('#poolFoot').textContent = more > 0 ? `+ ${more} more deals in pool` : '';
  $('#poolFoot').hidden = more <= 0;
}

/**
 * Why another deal can't be added right now — role, a read-only tranche, or the deal cap.
 * Returns null when adding is fine.
 */
function whyCantAdd() {
  const role = actingRole();
  if (!may(role, CAPS.BUILD)) return whyBlocked(role, CAPS.BUILD);
  if (!builderEditable()) {
    return `${S.loadedTranche?.name ?? 'This tranche'} is read-only — it holds real deals. Nothing here writes to CRM.`;
  }
  const cap = dealCapState(S.picked.size);
  if (cap.level === 'full') return cap.message;
  return null;
}

function dealRow(d) {
  const p = priced(d);
  const inTranche = S.picked.has(d.id);
  const role = actingRole();
  // Removing an already-added deal stays available whenever the tranche itself is editable —
  // only ADDING is capped, or you could never get back under the limit.
  const blocked = whyCantAdd();
  const mayBuild = inTranche ? (may(role, CAPS.BUILD) && builderEditable()) : !blocked;

  const tr = el('tr');

  const c1 = el('td');
  c1.append(el('div', 'dname', d.Deal_Name));
  c1.append(el('div', 'dsub', `${d.Account_Name ?? '—'} · ${d.Deal_Type ?? ''}`));
  tr.append(c1);

  tr.append(el('td', '', d.Customer_State ?? '—'));

  const c3 = el('td');
  for (const t of tagsFor(d)) {
    const s = el('span', `tag ${t.key}`, t.label);
    s.title = t.title;
    c3.append(s);
  }
  tr.append(c3);

  const c4 = el('td', 'r');
  if (p.eligible) {
    const bosLine = el('div', 'bos-line', money(p.calc.bos));
    bosLine.style.cursor = 'pointer';
    bosLine.title = 'Click to see the math';
    bosLine.onclick = () => dealMathModal(d, p);
    c4.append(bosLine);
    c4.append(el('div', 'dsub', `IC ${money(p.calc.investorContribution)}`));
  } else {
    // Name the rubric that is unpriced rather than a vague "not eligible" — this is the
    // whole point of the lookup: "If the pricing is not there, it tells you it's not there."
    c4.append(el('div', 'blocked', 'No pricing'));
    c4.append(el('div', 'dsub', p.gap?.reason ?? 'Rubric not priced'));
  }
  tr.append(c4);

  const c5 = el('td', 'c');
  if (p.eligible) {
    const b = el('button', `mini ${inTranche ? 'in' : ''}`, inTranche ? '✓' : 'Add');
    b.disabled = !mayBuild;
    if (!mayBuild) b.title = blocked ?? whyBlocked(role, CAPS.BUILD);
    b.onclick = () => { inTranche ? S.picked.delete(d.id) : S.picked.add(d.id); render(); };
    c5.append(b);
  } else {
    // Fixable in place, without leaving the tranche you were building.
    const mayPrice = may(role, CAPS.PRICING);
    const b = el('button', 'mini', 'Add pricing');
    b.disabled = !mayPrice;
    b.title = mayPrice ? 'Add this rate to the investor matrix' : whyBlocked(role, CAPS.PRICING);
    b.onclick = () => addPricingModal(d, p.gap);
    c5.append(b);
  }
  tr.append(c5);

  return tr;
}

function renderSummary() {
  const rows = pickedRows();
  const t = trancheTotals(rows, S.adders);
  $('#sCount').textContent = t.count;
  $('#sIC').textContent = moneyK(t.investorContribution);
  $('#sBosPct').textContent = pct(t.wBosPct);
  $('#sSowPct').textContent = pct(t.wSowPct);
  $('#sBos').textContent = money(t.bos);
  $('#sBasePrepay').textContent = money(t.prePay);
  $('#sFee').textContent = money(t.financingFee);
  $('#sPrePay').textContent = money(t.grossPrepay);
  $('#sItc').textContent = money(t.itc);
  $('#sKw').textContent = `${t.kw.toFixed(1)} kW`;
  $('#sKwh').textContent = `${t.kwh.toFixed(1)} kWh`;
}

/**
 * The financing-fee control. One blanket amount applied across every deal in the tranche;
 * per-deal overrides live on each row under "In this tranche". Gabe: "put adders across the
 * board, or put individual adders." Both feed the Bill of Sale through gross prepay.
 */
function renderFee() {
  const box = $('#adderLines');
  box.innerHTML = '';
  const mayEdit = may(actingRole(), CAPS.BUILD);

  const row = el('div', 'line');
  row.append(el('span', '', 'Blanket fee — all deals'));
  const right = el('span', 'v');
  const inp = el('input');
  inp.type = 'number';
  inp.min = '0';
  inp.step = '50';
  inp.value = S.feeBlanket || '';
  inp.placeholder = '0';
  inp.disabled = !mayEdit;
  inp.title = 'Applied to every deal in the tranche. Override a single deal on its row under "In this tranche".';
  inp.style.cssText = 'width:96px;text-align:right;font:inherit;border:0.5px solid var(--border);border-radius:4px;padding:2px 6px;';
  inp.onchange = (e) => { S.feeBlanket = Number(e.target.value) || 0; render(); };
  right.append(inp);
  row.append(right);
  box.append(row);

  const overrides = Object.keys(S.feeOverrides).filter((k) => S.feeOverrides[k] !== '' && S.feeOverrides[k] != null).length;
  const hint = el('div', 'dsub');
  hint.style.cssText = 'padding:3px 0 0';
  hint.textContent = overrides
    ? `${overrides} deal${overrides > 1 ? 's' : ''} with an individual fee (set on the row).`
    : 'Override a single deal on its row under “In this tranche”.';
  box.append(hint);

  // Total fee actually applied across the deals in the working tranche.
  const total = round2(pickedRows().reduce((s, r) => s + (r.calc.financingFee || 0), 0));
  $('#adderTotal').textContent = money(total);
}

function renderWorking() {
  const rows = pickedRows();
  const box = $('#working');
  box.innerHTML = '';
  const mayBuild = may(actingRole(), CAPS.BUILD) && builderEditable();

  if (!rows.length) {
    box.append(el('div', 'empty', 'No deals yet — add from the pool.'));
    return;
  }

  // The deal cap, surfaced where the deals are rather than only when a click fails.
  const cap = dealCapState(rows.length);
  if (cap.level !== 'ok') {
    const note = el('div', `banner ${cap.level === 'full' ? 'warn' : 'info'}`);
    note.append(el('strong', '', cap.level === 'full' ? `${rows.length} deals — ` : ''));
    note.append(el('span', '', cap.message));
    box.append(note);
  }

  for (const r of rows.slice(0, 40)) {
    const row = el('div', 'wrow');
    const l = el('div');
    l.append(el('div', '', r.deal.Deal_Name.slice(0, 42)));
    l.append(el('div', 'dsub', `${r.deal.Account_Name ?? '—'} · ${r.deal.Customer_State}`));
    // Per-deal financing fee override — Gabe's "individual adders". Blank = use the blanket.
    const feeWrap = el('label', 'wfee');
    feeWrap.append(el('span', 'dsub', 'Fee $'));
    const feeInp = el('input');
    feeInp.type = 'number';
    feeInp.min = '0';
    feeInp.step = '50';
    feeInp.value = S.feeOverrides[r.deal.id] ?? '';
    feeInp.placeholder = String(S.feeBlanket || (num(r.deal.Commitment_Fee) ?? 0));
    feeInp.disabled = !mayBuild;
    feeInp.title = 'Financing fee for this deal only. Blank uses the blanket fee.';
    feeInp.onchange = (e) => {
      const v = e.target.value;
      if (v === '') delete S.feeOverrides[r.deal.id];
      else S.feeOverrides[r.deal.id] = Number(v) || 0;
      render();
    };
    feeWrap.append(feeInp);
    l.append(feeWrap);
    const rt = el('div', 'who-l');
    rt.append(el('span', 'amt', money(r.calc.bos)));
    const x = el('button', 'x', '✕');
    x.disabled = !mayBuild;
    x.onclick = () => { S.picked.delete(r.deal.id); render(); };
    rt.append(x);
    row.append(l, rt);
    box.append(row);
  }
  if (rows.length > 40) box.append(el('div', 'foot', `+ ${rows.length - 40} more`));
}

function renderActions() {
  const rows = pickedRows();
  const role = actingRole();
  const mayLock = may(role, CAPS.LOCK);

  // Lock applies to a CREATED tranche, not the working list — after Create the working
  // list is empty by design, so gating on it left Lock permanently disabled.
  const openTranches = sandbox.sandbox.tranches.filter((t) => t.status === 'Open');
  const lock = $('#lock');
  lock.disabled = !mayLock || !openTranches.length;
  lock.textContent = openTranches.length
    ? `Lock and generate documents (${openTranches.length})`
    : 'Lock and generate documents';
  const deny = $('#lockDeny');
  deny.textContent = mayLock ? '' : whyBlocked(role, CAPS.LOCK);
  deny.hidden = mayLock;

  // Create needs build rights AND sandbox mode; preview is read-only so it stays available.
  //
  // With an existing tranche loaded, Create is the WRONG action — it would create a second
  // tranche holding the same deals. The button becomes Update, or is refused outright on a
  // read-only tranche.
  const mayBuild = may(role, CAPS.BUILD);
  const create = $('#create');
  const loaded = S.loadedTranche;
  if (loaded && !loaded.error) {
    const d = trancheDelta();
    create.textContent = 'Update this tranche';
    create.disabled = !mayBuild || !loaded.editable || !d.dirty;
    create.title = !mayBuild ? whyBlocked(role, CAPS.BUILD)
      : !loaded.editable ? `${loaded.name} is read-only — it holds real deals.`
      : !d.dirty ? 'Nothing has changed yet — add, remove or re-date a deal first.'
      : `Apply ${d.summary} to ${loaded.name}`;
  } else {
    create.textContent = 'Create tranche';
    create.disabled = !mayBuild || !rows.length || !S.investorId;
    create.title = mayBuild ? '' : whyBlocked(role, CAPS.BUILD);
  }
  $('#preview').disabled = !rows.length;
  $('#status').className = `pill ${rows.length ? 'draft' : 'open'}`;
  $('#status').textContent = rows.length ? 'Draft' : 'Empty';

  const inv = investor();
  const gaps = inv ? pricingGaps(S.deals, inv) : [];
  const gbox = $('#gaps');
  gbox.innerHTML = '';
  if (gaps.length) {
    gbox.hidden = false;
    const blocked = gaps.reduce((s, g) => s + g.count, 0);
    gbox.append(el('div', 'sum-t', `Pricing gaps — ${blocked} deal${blocked > 1 ? 's' : ''} blocked, ${gaps.length} rubric${gaps.length > 1 ? 's' : ''}`));
    for (const g of gaps.slice(0, 5)) {
      const r = el('div', 'sum-row');
      const label = g.sow != null ? `${(g.sow * 100).toFixed(0)}% SOW · ${(g.tax * 100).toFixed(0)}% credit` : (g.state ?? '—');
      r.append(el('span', '', label), el('span', 'v', `${g.count} deal${g.count > 1 ? 's' : ''}`));
      gbox.append(r);
    }
    if (gaps.length > 5) gbox.append(el('div', 'sum-row', `+ ${gaps.length - 5} more — open Pricing matrix to fill them`));
  } else gbox.hidden = true;
}

/**
 * The strip along the bottom.
 *
 * Defaults to OPEN tranches, per Gabe: "it's better that I'd see the open ones — the open
 * ones are the ones that still need to manipulate." The Open view is sourced from the
 * complete open-tranche list rather than the six-most-recent, so nothing is hidden just
 * because six locked tranches happen to be newer, and every card can be opened straight
 * into the builder.
 */
function renderRecentFilter() {
  const head = $('#recentHead');
  if (!head) return;
  head.innerHTML = '';
  head.append(el('span', '', S.recentFilter === 'open' ? 'Open tranches' : 'Recent tranches'));
  const seg = el('div', 'recent-filter');
  for (const [key, label] of [['open', 'Open'], ['all', 'Recent']]) {
    const b = el('button', `mini ${S.recentFilter === key ? 'in' : ''}`, label);
    b.onclick = () => { S.recentFilter = key; render(); };
    seg.append(b);
  }
  head.append(seg);
}

function renderRecent() {
  renderRecentFilter();
  const box = $('#recent');
  box.innerHTML = '';
  const openOnly = S.recentFilter === 'open';

  // Sandbox tranches first, visibly marked — they are the ones this session created.
  for (const t of sandbox.sandbox.tranches.filter((t) => !openOnly || t.status === 'Open')) {
    const c = el('div', 'rcard sbx');
    c.append(el('div', 'd', `${t.id} · ${String(t.createdAt).slice(0, 10)}`));
    c.append(el('div', 'n', `${t.investorName} · ${t.dealIds.length} deals`));
    const bb = el('div', 'b');
    bb.append(el('span', '', moneyK(t.totals?.investorContributionWithAdders ?? t.totals?.bos)));
    const st = el('span', '', t.status);
    st.style.color = t.status === 'Locked' ? 'var(--text-success)' : 'var(--text-warning)';
    bb.append(st);
    c.append(bb);
    if (t.documents?.length) {
      for (const d of t.documents) c.append(el('div', 'dsub', `✓ ${d.name} — ${d.status}`));
    }
    const acts = el('div', 'rcard-acts');
    const open = el('button', 'mini', 'Open');
    open.onclick = () => trancheDetailModal({ name: t.name, investor: t.investorName, date: String(t.createdAt).slice(0, 10), status: t.status, dealIds: t.dealIds, documents: t.documents });
    acts.append(open);
    // Swaps are a post-lock amendment — they only apply once the tranche is Locked (Trevor).
    if (t.status === 'Locked' && may(actingRole(), CAPS.SWAP) && t.dealIds.length) {
      const sw = el('button', 'mini', 'Swap a deal');
      sw.onclick = () => swapModal({ id: t.id, name: t.name, dealIds: t.dealIds, live: false });
      acts.append(sw);
    }
    const rm = el('button', 'mini', 'Discard');
    rm.onclick = () => { sandbox.deleteTranche(t.id); render(); };
    acts.append(rm);
    c.append(acts);
    box.append(c);
  }

  // Open view reads the full open list; Recent view keeps the six-most-recent-by-date strip.
  //
  // Capped, and the overflow is STATED. There are ~80 open tranches in CRM (many stale —
  // some dated 2017 and 2020), so an uncapped strip is unreadable, and a silently truncated
  // one reads as "that's all of them". The switcher above, with its search, is the complete
  // list.
  const STRIP_MAX = 12;
  const allCrmCards = openOnly
    ? S.openTranches.map((t) => ({
        id: t.id, date: t.date, investor: t.name, deals: t.dealCount, total: null, status: 'Open',
      }))
    : S.recent;
  const crmCards = allCrmCards.slice(0, STRIP_MAX);
  const hiddenCards = allCrmCards.length - crmCards.length;

  const sandboxShown = sandbox.sandbox.tranches.filter((x) => !openOnly || x.status === 'Open').length;
  if (!crmCards.length && !sandboxShown) {
    box.append(el('div', 'empty', openOnly
      ? 'No open tranches — everything is locked or none created yet.'
      : 'No recent tranches.'));
  }

  for (const t of crmCards) {
    // Did WE create this one this session? If so, offer a real undo / swap.
    const mine = sandbox.liveCreatedFor(t.id);
    const c = el('div', mine ? 'rcard mine' : 'rcard');
    c.append(el('div', 'd', t.date + (mine ? ' · created here' : '')));
    c.append(el('div', 'n', `${t.investor} · ${t.deals ?? mine?.dealIds.length ?? '—'} deals`));
    const b = el('div', 'b');
    b.append(el('span', '', moneyK(t.total)));
    const st = el('span', '', t.status);
    st.style.color = t.status === 'Locked' ? 'var(--text-success)' : 'var(--text-warning)';
    b.append(st);
    c.append(b);

    const acts = el('div', 'rcard-acts');
    const open = el('button', 'mini', 'Open');
    open.onclick = () => trancheDetailModal({ name: mine?.name ?? t.investor, investor: t.investor, date: t.date, status: t.status, dealIds: mine?.dealIds ?? null, dealCount: t.deals });
    acts.append(open);
    // The second way into the switcher — Gabe wants to hop between open tranches quickly.
    if (t.status === 'Open' && t.id) {
      const build = el('button', 'mini', 'Build into this');
      build.onclick = () => { if (confirmDiscard()) openTrancheIntoBuilder(t.id); };
      acts.append(build);
    }
    if (mine && may(actingRole(), CAPS.BUILD)) {
      // Post-lock only: swaps amend a locked (sold) tranche, not an open one.
      if (t.status === 'Locked' && may(actingRole(), CAPS.SWAP) && mine.dealIds?.length) {
        const sw = el('button', 'mini', 'Swap a deal');
        sw.onclick = () => swapModal({ id: t.id, name: mine.name ?? t.investor, dealIds: mine.dealIds, live: true });
        acts.append(sw);
      }
      const undo = el('button', 'mini', 'Undo (un-assign + delete)');
      undo.onclick = () => undoLive(t.id, undo);
      acts.append(undo);
    }
    c.append(acts);
    box.append(c);
  }

  if (hiddenCards > 0) {
    box.append(el('div', 'empty',
      `+ ${hiddenCards} more open tranche${hiddenCards === 1 ? '' : 's'} — use the Open tranche search at the top.`));
  }
}

