/**
 * Swap one deal out of a tranche and (optionally) one in.
 *
 * In CRM this is two effects, because a swap record does not itself move deals: a
 * Tranche_Swap_Records ledger row, plus reassigning the deals' Tranche lookup (out → back to
 * the pool, in → onto the tranche). Test deals only. Sandbox-created tranches do the same
 * thing locally so the browser demo behaves identically.
 */
function swapModal(tranche) {
  const heldIds = new Set((tranche.dealIds ?? []).map(String));
  const held = S.deals.filter((d) => heldIds.has(String(d.id)));
  // Candidates to swap in: available test deals not already in this tranche.
  const candidates = dealsInPool('available').filter((d) => !heldIds.has(String(d.id)));
  let outId = held[0] ? String(held[0].id) : null;
  let inId = null;

  openModal('Swap a deal', (b) => {
    b.append(el('p', 'note',
      tranche.live
        ? 'Amends a locked tranche: writes a real Tranche Swap Record and moves the deals in CRM — the one you remove returns to the pool, the one you add joins the tranche. Test deals only.'
        : 'Sandbox: amends this locked tranche locally, exactly as the CRM swap would — a swap record plus a tranche reassignment.'));

    const cols = el('div', 'swap-cols');

    const outCol = el('div', 'swap-col');
    outCol.append(el('div', 'sum-t', 'Remove from tranche'));
    for (const d of held) {
      const row = el('label', 'swap-opt');
      const r = el('input'); r.type = 'radio'; r.name = 'swapout'; r.checked = String(d.id) === outId;
      r.onchange = () => { outId = String(d.id); };
      row.append(r, el('span', '', `${d.Deal_Name} · ${moneyK(num(d.Amount))}`));
      outCol.append(row);
    }
    cols.append(outCol);

    const inCol = el('div', 'swap-col');
    inCol.append(el('div', 'sum-t', `Add from available (${candidates.length})`));
    const none = el('label', 'swap-opt');
    const nr = el('input'); nr.type = 'radio'; nr.name = 'swapin'; nr.checked = true;
    nr.onchange = () => { inId = null; };
    none.append(nr, el('span', 'dsub', 'Remove only — add nothing'));
    inCol.append(none);
    for (const d of candidates.slice(0, 40)) {
      const row = el('label', 'swap-opt');
      const r = el('input'); r.type = 'radio'; r.name = 'swapin';
      r.onchange = () => { inId = String(d.id); };
      row.append(r, el('span', '', `${d.Deal_Name} · ${moneyK(num(d.Amount))}`));
      inCol.append(row);
    }
    cols.append(inCol);
    b.append(cols);

    const status = el('p', 'note', '');
    b.append(status);

    const go = el('button', 'primary', 'Apply swap');
    go.onclick = async () => {
      if (!outId) { status.textContent = 'Pick a deal to remove.'; return; }
      go.disabled = true; go.textContent = 'Applying…';
      try {
        await applySwap(tranche, outId, inId);
        closeModal();
        render();
      } catch (e) {
        go.disabled = false; go.textContent = 'Apply swap';
        status.style.color = 'var(--text-danger)';
        status.textContent = 'Swap failed: ' + (e?.message || String(e));
        console.error('swap failed', e);
      }
    };
    b.append(go);
  });
}

async function applySwap(tranche, outId, inId) {
  const dealOut = S.deals.find((d) => String(d.id) === String(outId));
  const dealIn = inId ? S.deals.find((d) => String(d.id) === String(inId)) : null;

  const live = tranche.live && isLive() && mode.isSandbox && TRANCHE_SWAP_WRITES;
  if (live) {
    await zohoSwapTrancheLive({
      trancheId: tranche.id,
      trancheName: tranche.name,
      dealsOut: dealOut ? [dealOut] : [],
      dealsIn: dealIn ? [dealIn] : [],
    });
    sandbox.applyLiveSwap(tranche.id, outId, inId);
    S.deals = await loadDeals();
    [S.recent, S.openTranches] = await Promise.all([loadRecentTranches(), loadOpenTranches()]);
  } else {
    // Local sandbox tranche (or standalone preview).
    sandbox.swapTranche(tranche.id, outId, inId);
  }
}

/** Reverse a tranche the widget created: un-assign its deals and delete the record. */
async function undoLive(trancheId, btn) {
  const rec = sandbox.liveCreatedFor(trancheId);
  if (!rec) return;
  btn.disabled = true;
  btn.textContent = 'Undoing…';
  try {
    const res = await zohoUndoTrancheLive({ trancheId, dealIds: rec.dealIds });
    sandbox.forgetLiveCreate(trancheId);
    // Undo DELETES the tranche. If it is still loaded in the builder, drop it — otherwise the
    // switcher keeps offering a record that no longer exists and opening it queries a ghost.
    if (String(S.loadedTranche?.id) === String(trancheId)) resetToNewTranche();
    S.deals = await loadDeals();      // the freed deals return to the pool
    [S.recent, S.openTranches] = await Promise.all([loadRecentTranches(), loadOpenTranches()]);
    if (res.errors.length) console.warn('undo had errors', res.errors);
    render();
  } catch (e) {
    btn.disabled = false;
    btn.textContent = 'Undo failed — retry';
    console.error('undo failed', e);
  }
}

/* ------------------------------------------------------------------ formula trace */

/**
 * Render a list of explain-steps as a "show the math" block. Every number the tool shows
 * can be expanded into this, so Gabe sees the formula and the substituted values behind it.
 */
function traceBlock(steps) {
  const wrap = el('div', 'trace');
  for (const st of steps) {
    const row = el('div', `trace-row src-${st.source?.replace(/[^a-z]/gi, '') || 'computed'}`);
    const head = el('div', 'trace-head');
    head.append(el('span', 'trace-label', st.label));
    head.append(el('span', 'trace-value', st.value));
    row.append(head);
    const f = el('div', 'trace-formula');
    f.append(el('code', '', st.formula));
    if (st.substituted) { f.append(el('span', 'trace-eq', '=')); f.append(el('code', 'sub', st.substituted)); }
    row.append(f);
    const meta = el('div', 'trace-meta');
    if (st.source) meta.append(el('span', `trace-src src-${st.source.replace(/[^a-z]/gi, '')}`, st.source));
    if (st.note) meta.append(el('span', 'trace-note', st.note));
    row.append(meta);
    wrap.append(row);
  }
  return wrap;
}

/** What a suppressed CRM write would have done — shown so the demo is transparent. */
function actionBlock(act) {
  const wrap = el('div', 'action-trace');
  wrap.append(el('div', 'sum-t', 'What this would do in CRM'));
  for (const w of act.wouldWrite) {
    const r = el('div', 'act-row');
    r.append(el('code', 'act-op', w.op));
    r.append(el('span', 'act-target', w.target));
    r.append(el('span', 'act-detail', w.detail));
    wrap.append(r);
  }
  const n = el('p', 'note');
  n.append(el('strong', '', 'Suppressed. '), el('span', '', act.note.replace(/^Suppressed[^.]*\.\s*/, '')));
  wrap.append(n);
  return wrap;
}

/** An inline expandable "Show math" toggle. */
function showMath(container, steps) {
  const t = el('button', 'link', 'Show math');
  let open = false;
  let block = null;
  t.onclick = () => {
    open = !open;
    if (open) { block = traceBlock(steps); container.append(block); t.textContent = 'Hide math'; }
    else { block?.remove(); t.textContent = 'Show math'; }
  };
  container.append(t);
}

