/**
 * Data access. One seam, two sources.
 *
 *   LIVE   — COQL over the logged-in user's OAuth session (inside CRM)
 *   SAMPLE — anonymised real economics from Tranche 77 (standalone / local dev)
 *
 * The widget picks automatically: framed by Zoho ⇒ live, otherwise sample. Force with
 * ?source=sample or ?source=live.
 */

import { coql, customViews, inZoho } from './zoho.js';
import { SAMPLE_DEALS } from './sample-deals.js';
import { loadLiveDeals, loadLiveInvestors, loadLiveTranches, loadLiveOpenTranches, loadLiveTrancheDeals, POOL_QUERIES } from './live.js';
import { lookup, gapsFor } from './pricing.js';
import { taxCreditFor, isEC, num } from './calc.js';
import { loadInvestorPricing, lookupLive, productFor } from './livePricing.js';
import { committedDealIds } from './sandbox.js';

export { POOL_QUERIES };

const qs = new URLSearchParams(typeof location !== 'undefined' ? location.search : '');
export const SOURCE = qs.get('source') || (inZoho() ? 'live' : 'sample');
export const isLive = () => SOURCE === 'live';

/* ------------------------------------------------------------------ pools */

/**
 * The three deal pools.
 *
 * PROVISIONAL. These encode Gabe's screen-share description, not verified CRM view
 * criteria. `loadPoolViews()` fetches the real custom views at runtime so we can show
 * what CRM actually thinks — reconciling the two is a question for Gabe.
 *
 * Pools are not naturally disjoint: an M1 Lite is also un-approved and un-purchasable,
 * so it matches "Soon-to-be M1" too. Gabe described Lite as a double filter ("if it's
 * permit and it's an M1, it's an M1 Lite") — permit is what pulls a deal out of the
 * normal flow. Hence MATCH_ORDER tests permit first while POOLS keeps his display order.
 */
export const POOLS = [
  {
    key: 'available',
    label: 'M1 available for purchase',
    hint: 'Prepped for sale — M1 approved or flagged available, not yet in a tranche',
    // Plain-English criteria surfaced in the UI so anyone can see why a deal is (or isn't)
    // in a pool. Keep this in step with POOL_QUERIES.available.where.
    criteria: [
      'Stage is M1',
      'M1 certificate signed, OR flagged available for purchase',
      'not already assigned to a tranche',
    ],
    match: (d) => (d.Avail_for_Purchase === true || d.M1_Approved === true) && d.__doc !== 'Permit',
  },
  {
    key: 'soon',
    label: 'Soon-to-be M1',
    hint: 'M1 stage, not yet approved or flagged available, not yet in a tranche',
    subdivide: true, // Gabe's two subdivisions: has a final / no final
    // Broadened to catch every remaining M1 deal so nothing falls through the cracks —
    // "when we're in the test fund, show all of them."
    criteria: [
      'Stage is M1',
      'not yet M1-approved and not flagged available',
      'not already assigned to a tranche',
    ],
    match: (d) =>
      d.Stage === 'M1' &&
      d.Avail_for_Purchase !== true &&
      d.M1_Approved !== true &&
      d.__doc !== 'Permit',
  },
  {
    key: 'lite',
    label: 'M1 lite',
    hint: 'Marked Permit rather than Signed Job Card',
    criteria: [
      'Stage is M1',
      "Permit_Status is 'Permit' (not 'Job Card Signed')",
      'not already assigned to a tranche',
    ],
    match: (d) => d.Stage === 'M1' && d.__doc === 'Permit',
  },
];

const MATCH_ORDER = ['lite', 'available', 'soon'];

export function poolFor(deal) {
  // Live rows arrive tagged by the query that returned them. Trust that over re-deriving:
  // the server-side WHERE *is* the pool definition, and the client-side `match` predicates
  // below rely on `__doc`/`__ntp` markers that only sample rows carry. Without this, live
  // M1 Lite renders empty and Lite deals leak into Soon-to-be M1.
  if (deal.__pool) return deal.__pool;
  for (const key of MATCH_ORDER) {
    const p = POOLS.find((x) => x.key === key);
    if (p.match(deal)) return key;
  }
  return null;
}

/**
 * Gabe's two subdivisions of Soon-to-be M1: "the ones with final, and the ones here".
 *
 * We do not know which CRM field means "has a final". `Final_Certificate_Approved` turned
 * out to be the M2 gate, and `Final_Inspection_Received` / `Final_Invoice` are both dead
 * fields ("XFinal ..."). Sample rows carry `__final`; live rows carry nothing.
 *
 * So rather than invent a field and mislabel every deal, `canSubdivide()` reports whether
 * the data can answer the question at all, and the UI says so when it can't. This is an
 * open question for Gabe, not a bug to paper over.
 */
export const hasFinal = (d) => d.__final === true;
export const canSubdivide = (deals) => deals.some((d) => d.__final !== undefined && d.__final !== null);

/**
 * Everything a user needs to understand a pool: the plain-English rule, the exact COQL
 * WHERE it runs live, how confident we are in the definition, and what it returned last
 * fetch. Surfaced in the UI on the active tab and on hover.
 */
export function poolCriteria(key) {
  const pool = POOLS.find((p) => p.key === key);
  const q = POOL_QUERIES[key];
  const count = poolCounts.value?.[key];
  return {
    label: pool?.label ?? key,
    criteria: pool?.criteria ?? [pool?.hint].filter(Boolean),
    coql: q?.where ?? null,
    confidence: q?.confidence ?? null,
    count: typeof count === 'number' ? count : null,
    countError: typeof count === 'string' ? count : null,
    live: isLive(),
  };
}

/** What CRM actually has. Read-only reconnaissance — never throws. */
export async function loadPoolViews() {
  if (!isLive()) return [];
  try {
    const views = await customViews('Deals');
    const want = /soon|available for purchase|m1\s*(lite|light)/i;
    return views.filter((v) => want.test(v.name ?? '')).map((v) => ({ id: v.id, name: v.name }));
  } catch (e) {
    console.warn('custom view probe failed', e);
    return [];
  }
}

/* ------------------------------------------------------------------ deals */

/**
 * Every name here was confirmed against the live org by running it in COQL.
 *
 * Deliberately excluded, because they 400 the whole query:
 *   Additional_Pre_Pay   — not a Deals field at all; it was a derived column in the
 *                          tranche Excel export. CRM's Pre_Pay_Amount formula is the
 *                          authority on live records.
 *   Full_Electricity_Price — likewise absent.
 *   Tranche_Number       — INVALID_QUERY live despite appearing in the metadata export.
 *
 * Note `Battery_kW_Size`: the api_name says kW, the field label says kWh. The label is
 * the honest one (13.5, 27, 40.5 are kWh). Do not "correct" the api_name.
 */
const DEAL_FIELDS = [
  'id', 'Deal_Name', 'Customer_State', 'Stage', 'Amount', 'System_Size',
  'Battery_kW_Size', 'Deal_Type',
  'Pre_Pay_Pct_of_Statement_of_Work', 'Pre_Paid_Percentage_of_Bill_of_Sale',
  'Pre_Pay_Amount', 'Bill_of_Sale_Amount', 'Total_Investor_Contribution',
  'Energy_Community_Tax_Eligible', 'Energy_Community_Title',
  'Domestic_Content', 'Tax_Credit_Percentage', 'ITC_Amount',
  'Safe_Harbor_Strategy', 'Energized_Date', 'Begin_Construction_Date',
  'Avail_for_Purchase', 'M1_Approved', 'Permit_Status',
  // Lookup traversal works in COQL — pulls the installer and tranche in one round trip.
  'Account_Name.Account_Name', 'Tranche.Name', 'Tranche.Tranche_Status',
];

/**
 * Records why live mode fell back, so the UI can say so instead of showing a dead page.
 * Being framed by Zoho is not proof the SDK handshake succeeded or that COQL is allowed —
 * separate "the widget loaded" from "the data layer works", because they fail for
 * completely different reasons and the fixes live in different places.
 */
export const fallback = { active: false, reason: null };

/**
 * Sandbox vs Live — one switch that sets both what you see and what you can do.
 *
 *   sandbox (default) — TEST records only, and every action is ON (create, lock, price,
 *                       swap) so Gabe can actually play. All local; nothing reaches CRM.
 *   live              — real records only (test excluded), and every action is OFF.
 *                       Pure read-only viewing of production data.
 *
 * Either way no data is written to CRM — `WRITES_ENABLED` stays false. The difference is
 * whether the browser-only sandbox actions are available at all.
 */
export const mode = {
  value: (typeof localStorage !== 'undefined' && localStorage.getItem('maxwell-mode')) || 'sandbox',
  set(v) {
    this.value = v === 'live' ? 'live' : 'sandbox';
    try { localStorage.setItem('maxwell-mode', this.value); } catch { /* private mode */ }
  },
  get isSandbox() { return this.value === 'sandbox'; },
  /** Sandbox shows test records; live shows real records (test excluded). */
  get testClause() { return this.value === 'sandbox' ? 'test' : 'real'; },
};

export async function loadDeals() {
  if (!isLive()) {
    // Standalone preview has no CRM. Sample rows stand in for sandbox (test) data; in live
    // mode there are no real records to show, so it's empty — honest about the mode.
    return mode.isSandbox ? structuredClone(SAMPLE_DEALS) : [];
  }
  try {
    const { deals, perPool } = await loadLiveDeals(mode.testClause);
    poolCounts.value = perPool;
    if (!deals.length) {
      // No matching records is a real, expected state (e.g. no test M1s prepped yet), not a
      // failure — don't fall back to sample data and mask it.
      fallback.active = false;
      return [];
    }
    return deals;
  } catch (e) {
    fallback.active = true;
    fallback.reason = e?.message || String(e);
    console.warn('live deal load failed — falling back to sample data', e);
    return structuredClone(SAMPLE_DEALS);
  }
}

/** Per-pool row counts from the last live fetch, surfaced in the Connection panel. */
export const poolCounts = { value: {} };

