export async function loadInvestors() {
  // Sandbox shows only Gabe's two named investors; live shows every real investor account.
  if (mode.isSandbox) return structuredClone(SANDBOX_INVESTORS);
  if (!isLive()) return structuredClone(INVESTORS);
  try {
    const rows = await loadLiveInvestors();
    if (!rows.length) throw new Error('no investor records returned');
    return rows.map((r) => ({
      id: String(r.id),
      // The `Investor` module's display field is `Name`; the widget uses Account_Name
      // everywhere, so map it across. This id matches Investor_Pricing.Investor, so the deal
      // pricing lookup now resolves.
      Account_Name: r.Name ?? r.Account_Name,
      // No per-investor BoS multiplier exists in CRM; pricing comes from the Investor_Pricing
      // matrix, and an unpriced investor falls back to CRM's own Bill_of_Sale_Amount.
      bosMultiplier: null,
      real: true,
      note: 'Live investor — pricing reads from its Investor_Pricing record',
    }));
  } catch (e) {
    console.warn('investor load failed, using configured list', e);
    return structuredClone(INVESTORS);
  }
}

/* ------------------------------------------------------------------ pricing */

/**
 * Per-investor pricing. Returns null when the investor has no pricing for a deal's
 * state — which means NOT ELIGIBLE, and the UI must say so rather than hide the deal.
 * That null is load-bearing; it's Gabe's stated requirement.
 *
 * SHAPE IS PROVISIONAL. Real Investor_Pricing columns unread. What we do know from
 * Tranche 77: the true pricing key is (Pre_Pay_Pct_of_SOW × Tax_Credit_Percentage),
 * where tax credit comes from the EC/DC rubric — see FINDINGS.md §2.
 */
/**
 * Price a deal for an investor.
 *
 * Keyed on the DEAL'S PERCENTAGE, not its state. Gabe:
 *   "when I add a deal, that's it, it'll check the percentage. Look up the pricing, add it
 *    in there. If the pricing is not there, it tells you it's not there."
 *
 * An earlier version gated on a state list. That was wrong — nothing in either transcript
 * supports state as the *price* key, and Tranche 77 shows every (SOW %, tax credit) pair
 * mapping to exactly one bill-of-sale percentage regardless of state. State may still be a
 * separate eligibility axis ("if there's no pricing for that state you can't sell it") —
 * that's an open question for Gabe, not something to guess at here.
 *
 * Returns null when the investor has no row for the deal's rubric. That null is
 * load-bearing: it drives the inline "add pricing" flow rather than hiding the deal.
 */
export function priceFor(deal, investor) {
  if (!investor) return null;
  const tc = taxCreditFor(deal);

  // Real CRM pricing wins when the investor has it. A miss then is a genuine gap — we do
  // NOT fall back to the local stopgap, because "the investor doesn't price this rubric"
  // is exactly the filtering Gabe wants to see.
  if (investor.livePricing?.found) {
    const hit = lookupLive(investor.livePricing, deal, tc.value, isEC(deal));
    return hit ? { bosPct: hit.bosPct, sow: hit.matchedSow, tax: tc.value, source: 'crm', state: hit.state, product: hit.product } : null;
  }

  // Stopgap: the local matrix (starter rates / manually entered) for investors with no
  // pricing in CRM yet — which is the case for the demo investors.
  const { row, sow, tax, reason } = lookup(investor, deal, tc.value);
  if (!row) return null;
  return { bosPct: row.bosPct, sow, tax, source: row.source, reason };
}

/** Why a deal has no price — so the UI can name the rubric instead of just greying out. */
export function priceGapFor(deal, investor) {
  if (!investor) return null;
  const tc = taxCreditFor(deal);
  if (investor.livePricing?.found) {
    // CRM-priced investor with no rate for this rubric.
    return {
      row: null,
      sow: num(deal.Pre_Pay_Pct_of_Statement_of_Work),
      tax: tc.value,
      reason: `No CRM rate for ${deal.Customer_State} · ${productFor(deal)} at ${(tc.value * 100).toFixed(0)}% credit`,
    };
  }
  const res = lookup(investor, deal, tc.value);
  return res.row ? null : res;
}

/**
 * Load an investor's real CRM pricing once and cache it on the investor object. No-op
 * outside CRM (the stopgap covers standalone) or if already attempted.
 */
export async function ensureInvestorPricing(investor) {
  if (!investor || !isLive()) return;
  if (investor.livePricing !== undefined) return; // already loaded (or found none)
  try {
    investor.livePricing = await loadInvestorPricing(investor.id);
  } catch (e) {
    console.warn('ensureInvestorPricing failed', e);
    investor.livePricing = { found: false, error: e?.message || String(e) };
  }
}

/**
 * Load live pricing for EVERY investor, in parallel. Maximise Margin compares deals across
 * all investors, so it needs every investor's matrix — not just the selected one. Without
 * this the comparison silently collapses to whichever investor was already loaded.
 */
export async function ensureAllInvestorPricing(investors) {
  await Promise.all((investors ?? []).map((inv) => ensureInvestorPricing(inv)));
}

/** Unpriced rubrics across a set of deals, most common first. */
export function pricingGaps(deals, investor) {
  if (!investor) return [];
  return gapsFor(investor, deals, (d) => taxCreditFor(d).value);
}

