/**
 * How many deals a tranche can hold before the CRM side starts losing them.
 *
 * HARD is the verified ceiling: `trancheBtn_updtTotals1` — the Update Totals button that
 * fills the System Schedule subform AND the WM_JSON document payload — reads its deals
 * with one un-paginated `zoho.crm.searchRecords`, which returns 200 and stops. Past that
 * the tranche still looks complete in CRM while its paperwork quietly isn't.
 *
 * SOFT is Gabe's stated subform limit. He said 100; the export says the data cap is 200.
 * Both can be true (a display cap and a fetch cap are different things) and we have not
 * confirmed which bites first, so the widget warns at the lower number and refuses at the
 * higher one rather than pretending to know.
 */
export const DEAL_LIMIT = { soft: 100, hard: 200 };

/**
 * Where a tranche of `count` deals sits against the cap, and what to say about it.
 *
 * A pure function so the rule is testable and stated once — the pool's Add button, the
 * working list's banner and anything added later all read the same verdict rather than
 * each re-deriving it from the numbers.
 */
export function dealCapState(count) {
  if (count >= DEAL_LIMIT.hard) {
    return {
      level: 'full',
      message:
        `${DEAL_LIMIT.hard}-deal limit reached. The CRM Update Totals button fetches a tranche's ` +
        `deals in one un-paged call that stops at ${DEAL_LIMIT.hard}, so a bigger tranche generates ` +
        `its System Schedule and documents short, with no error. Split into a second tranche.`,
    };
  }
  if (count >= DEAL_LIMIT.soft) {
    return {
      level: 'warn',
      message:
        `${count} deals. Gabe put the subform limit at ${DEAL_LIMIT.soft}; the CRM function behind ` +
        `Update Totals stops fetching at ${DEAL_LIMIT.hard}. Which bites first isn't confirmed, so ` +
        `check the generated documents against this list before locking.`,
    };
  }
  return { level: 'ok', message: null };
}

/** Sample open tranches, so the switcher is exercisable in standalone dev. */
const SAMPLE_OPEN = [
  { id: 'sample-open-1', name: 'Sample Investor Tranche 2026-07-02', date: '2026-07-02', dealCount: 6 },
  { id: 'sample-open-2', name: 'Sample Investor Tranche 2026-07-21', date: '2026-07-21', dealCount: 4 },
];

/**
 * Every OPEN tranche, for the switcher.
 *
 * `investorId` is the raw `Tranches.Investor` lookup id — the caller matches it against the
 * loaded investor list (ids come from the same `Investor` module) instead of paying a
 * second query per tranche.
 */
export async function loadOpenTranches() {
  if (!isLive()) {
    return SAMPLE_OPEN.map((t) => ({ ...t, investorId: null, status: 'Open', sample: true }));
  }
  try {
    const rows = await loadLiveOpenTranches();
    return rows.map((r) => ({
      id: String(r.id),
      name: r.Name,
      date: String(r.Tranche_Date ?? '').slice(0, 10),
      investorId: r.Investor?.id ? String(r.Investor.id) : null,
      status: r.Tranche_Status,
      dealCount: null, // unknown until the tranche is opened; counting every one up front is N queries
    }));
  } catch (e) {
    console.warn('open tranches failed', e);
    return [];
  }
}

/** The deals already sitting in a tranche. Paged — see loadLiveTrancheDeals. */
export async function loadTrancheDeals(trancheId) {
  if (!isLive()) {
    const n = SAMPLE_OPEN.find((t) => t.id === trancheId)?.dealCount ?? 5;
    // Take from the tail so these don't collide with the deals already shown in the pools.
    return structuredClone(SAMPLE_DEALS).slice(-n).map((d) => ({ ...d, Tranche: { id: trancheId } }));
  }
  return loadLiveTrancheDeals(trancheId);
}
